  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.scss']
})
export class AppComponent {
  title = 'pals-web';
}
<qrcode
  [qrdata]="'abhimanyu'"
  [width]="256"
  [errorCorrectionLevel]="'M'"
></qrcode>

